// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(uint256 value, bytes32 hash) public {
        vm.assume(value <= 2 ether);
        address actor = address(this);
        vm.deal(actor, value);
        vm.prank(actor);

        bool ok;
        try c.lockInGuess{value: value}(hash) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (value == 1 ether));
    }
}
